package org.mockito.internal.invocation;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Test;
import org.mockito.exceptions.PrintableInvocation;
import org.mockito.internal.debugging.Location;
import org.mockito.internal.invocation.Invocation;
import org.mockito.internal.matchers.CapturesArguments;
import org.mockito.internal.reporting.PrintSettings;
import org.mockito.internal.reporting.PrintingFriendlyInvocation;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class InvocationMatcher_hasSameMethod_TriageGen2Test {

    @Test
    public void testHasSameMethod_ReturnsTrueWhenMethodsAreEqual() throws NoSuchMethodException {
        // Arrange
        Method method = String.class.getMethod("length");

        Invocation invocation = mock(Invocation.class);
        when(invocation.getMethod()).thenReturn(method);

        Invocation candidate = mock(Invocation.class);
        when(candidate.getMethod()).thenReturn(method);

        InvocationMatcher matcher = new InvocationMatcher(invocation, Collections.emptyList());

        // Act
        boolean result = matcher.hasSameMethod(candidate);

        // Assert
        assertTrue("Should return true when both methods are the same instance", result);
    }






}

